class LockingTree {
    vector<int> parent;
    vector<int> locked;
    vector<vector<int>> children;
public:
    LockingTree(vector<int>& parent) : parent(parent), locked(parent.size(), 0), children(parent.size()) {
        for (int i = 1; i < (int)parent.size(); i++) {
            children[parent[i]].push_back(i);
        }
    }

    bool lock(int num, int user) {
        if (locked[num] == 0) {
            locked[num] = user;
            return true;
        }
        return false;
    }

    bool unlock(int num, int user) {
        if (locked[num] == user) {
            locked[num] = 0;
            return true;
        }
        return false;
    }

    bool upgrade(int num, int user) {
        if (locked[num] != 0) return false;
        int curr = parent[num];
        while (curr != -1) {
            if (locked[curr] != 0) return false;
            curr = parent[curr];
        }
        vector<int> lockedDescendants;
        auto dfs = [&](auto& self, int u) -> void {
            if (locked[u] != 0) lockedDescendants.push_back(u);
            for (int v : children[u]) self(self, v);
        };
        for (int child : children[num]) dfs(dfs, child);
        if (lockedDescendants.empty()) return false;
        locked[num] = user;
        for (int u : lockedDescendants) locked[u] = 0;
        return true;
    }
};

import java.util.*;

class LockingTree {
    private int[] parent;
    private int[] locked;
    private List<List<Integer>> children;

    public LockingTree(int[] parent) {
        this.parent = parent;
        int n = parent.length;
        this.locked = new int[n];
        this.children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 1; i < n; i++) {
            children.get(parent[i]).add(i);
        }
    }

    public boolean lock(int num, int user) {
        if (locked[num] == 0) {
            locked[num] = user;
            return true;
        }
        return false;
    }

    public boolean unlock(int num, int user) {
        if (locked[num] == user) {
            locked[num] = 0;
            return true;
        }
        return false;
    }

    public boolean upgrade(int num, int user) {
        if (locked[num] != 0) return false;
        int curr = parent[num];
        while (curr != -1) {
            if (locked[curr] != 0) return false;
            curr = parent[curr];
        }
        List<Integer> lockedDescendants = new ArrayList<>();
        dfs(num, false, lockedDescendants);
        if (lockedDescendants.isEmpty()) return false;
        locked[num] = user;
        for (int u : lockedDescendants) locked[u] = 0;
        return true;
    }

    private void dfs(int u, boolean includeSelf, List<Integer> list) {
        if (includeSelf && locked[u] != 0) list.add(u);
        for (int v : children.get(u)) {
            dfs(v, true, list);
        }
    }
}

