LockingTree.prototype.upgrade = function(num, user) {
  if (this.locked[num] !== 0) return false;
  let curr = this.parent[num];
  while (curr !== -1) {
    if (this.locked[curr] !== 0) return false;
    curr = this.parent[curr];
  }
  const lockedDescendants = [];
  const dfs = (u) => {
    if (this.locked[u] !== 0) lockedDescendants.push(u);
    for (const v of this.children[u]) dfs(v);
  };
